class Form(typing.Mapping[str, str], Content):
    """HTML form data, as an immutable multi-dict.
Form parameters, as a multi-dict."""

    def __init__(self, form: typing.Mapping[str, str | typing.Sequence[str]] | typing.Sequence[tuple[str, str]] | str | None=None) -> None:
        ...

    def encode(self) -> Stream:
