        for k, v in self._dict.items():
            multi_items.extend([(k, i) for i in v])
        return multi_items

def __eq__(self, other: typing.Any) -> bool:
        return (
            isinstance(other, Files) and
            sorted(self.multi_items()) == sorted(other.multi_items())
        )

