        ...

    def _handler(self, stream):
        ...

def __exit__(self, exc_type, exc_val, exc_tb):
        self.listener.close()
        self._executor.shutdown(wait=True)

def _serve(self):
        while stream := self.listener.accept():
            self._executor.submit(self._handler, stream)

def _handler(self, stream):
        try:
            self.handler(stream)
        finally:
            stream.close()

