        """
        Return a new Headers instance, removing the value of a key.

        Usage:

        h = httpx.Headers({"Accept": "*/*"})
        h = h.copy_remove("Accept")
        assert h == httpx.Headers({})
        """
        h = {k: v for k, v in self._dict.items() if k.lower() != key.lower()}
        return Headers(h)

