    @property
    def size(self) -> int | None:
        ...

def _read_next_section(self) -> bytes:
        if self._form_progress:
            # return a form item
            key, value = self._form_progress.pop(0)
            name = key.translate({10: "%0A", 13: "%0D", 34: "%22"})
            return (
                f"--{self._boundary}\r\n"
                f'Content-Disposition: form-data; name="{name}"\r\n'
                f"\r\n"
                f"{value}\r\n"
            ).encode("utf-8")
        elif self._files_progress and self._fin is None:
            # return start of a file item
            key, value = self._files_progress.pop(0)
            self._fin = open(value, 'rb')
            name = key.translate({10: "%0A", 13: "%0D", 34: "%22"})
            filename = os.path.basename(value)
            return (
                f"--{self._boundary}\r\n"
                f'Content-Disposition: form-data; name="{name}"; filename="{filename}"\r\n'
                f"\r\n"
            ).encode("utf-8")
        elif self._fin is not None:
            chunk = self._fin.read(64*1024)
            if chunk != b'':
                # return some bytes from file
                return chunk
            else:
                # return end of file item
                self._fin.close()
                self._fin = None
                return b"\r\n"
        elif not self._complete:
            # return final section of multipart
            self._complete = True
            return f"--{self._boundary}--\r\n".encode("utf-8")
        # return EOF marker
        return b""

def close(self) -> None:
        if self._fin is not None:
            self._fin.close()
            self._fin = None
        self._buffer.close()

